# -*- coding: utf-8 -*-
"""فصل ۳ (تحصیلات و رشد فکری) و فصل ۴ (زمینه‌ی فکری)."""

def ch3(D):
    D.h1("تحصیلات و رشد فکری", num="۳")

    D.h2("۳.۱. مسیر تحصیلی: از مهندسی به ادبیات")
    D.para("مسیر تحصیلی مک‌لوهان، خود بایانیه‌ای است درباره‌ی اینکه چگونه یک ذهن «غیرمتعارف»، به سمتی که بایست رفت، هدایت می‌شود. او نخست مهندس شد (در سایه‌ی پدر)، اما به‌سرعت فهمید که «درد» او در ادبیات و زبان است. این گذار، ساده‌تر از آنچه به نظر می‌رسد نبود: در ۱۹۲۸ وارد دانشگاه منیتوبا شد، از مهندسی به هنر گذشت، و در ادبیات انگلیسی ماندگار شد. در منیتوبا، با روش‌های «خوانش نزدیک» ادبیات آشنا شد — روشی که در کمبریج به دست ای.آر. جی. ریچاردز به بلوغ رسید.")

    D.h2("۳.۲. کمبریج و «نقد نو»: ریشه‌ی معرفت‌شناختی")
    D.para("دوره‌ی کمبریج (۱۹۳۴–۱۹۳۶) مهم‌ترین دورۀ شکل‌گیری فکری مک‌لوهان بود. ای.آر. جی. ریچاردز، بنیان‌گذار «نقد نو» (New Criticism) و نظریه‌پرداز زبان‌شناسی ادبی، به مک‌لوهان آموخت که «زبان» ابزاری‌ای است که معنی را می‌سازد، نه صرفا‌ً انتقال‌دهنده‌ای‌ای که معنای از پیش شکل‌گرفته را حمل می‌کند. این بینش — «زبان/رسانه، ادراک را می‌سازد» — مستقیماً به شعار «رسانه پیام است» منجر شد. دی.ژ. لیویس، هم‌دوره‌ی ریچاردز، نیز بر اهمیت «بافت» (context) و «سبک» (style) تأکید می‌کرد؛ نکاتی‌ای که مک‌لوهان در تحلیل رسانه‌های مختلف به کار گرفت.")
    D.para("رسالة‌ی دکتری مک‌لوهان در کمبریج، بر «سهمسه‌ی کلاسیک» (Trivium) و ادبیات کلاسیک یونانی-رومی متمرکز بود. این ریشه‌ی کلاسیک، توضیح می‌دهد چرا او تاریخ را به‌شکل «الگوهای تکرارشونده» (cyclical patterns) می‌خواند، نه به‌شکل خطیِ پیشرفت. مک‌لوهان بارها به «چهار عصر» (Tribal/Lithic/Gutenberg/Electronic) ارجاع داد — چارچوبی‌ای که از تاریخ‌نگری کلاسیک و همچنین از آثار هارولد اینیس گرفته شده بود.")

    D.h2("۳.۳. رشد تدریجی: از نقاد ادبی به نظریه‌پرداز رسانه")
    D.para("مک‌لوهان در سه مرحله، از نقاد ادبی به نظریه‌پرداز رسانه تبدیل شد:")
    D.bullet("مرحله‌ی اول (تا ۱۹۵۱): نقاد ادبی. آثار او (از جمله Preface to The Mechanical Bride, 1950) نقدهای ادبی و فرهنگی بودند. کتاب نخستش، عروس مکانیکی (1951)، هنوز در حوزه‌ی «فرهنگ عامه و ادبیات» قرار داشت.")
    D.bullet("مرحله‌ی دوم (۱۹۶۲–۱۹۶۴): شکست و اوج. کهکشان گوتنبرگ (1962) و درک رسانه‌ها (1964) دو کتابی‌ای بودند که او را از ادبیات به «اکولوژی رسانه» بردند. در این دو کتاب، مفهوم «رسانه به‌عنوان گسترشِ حس» (media as extension of senses) و تمایز «گرم/سرد» شکل گرفت.")
    D.bullet("مرحله‌ی سوم (۱۹۶۷–۱۹۸۰): رسوخ و بسط. در این دوره، مفاهیمش (روستای جهانی، تتراد، پیش‌بازخورد) به ابزاری برای تحلیل عصر الکترونیک تبدیل شدند و شاگردان و پیروان زیادی پیدا کرد.")

    D.h2("۳.۴. تأثیرات فکری کلیدی")
    D.table(
        headers=["چهره", "تأثیر بر مک‌لوهان"],
        rows=[
            ["هارولد اینیس (Harold Innis)", "مؤثرترین استاد. مفهوم «سوگیری رسانه» (time/space bias) و «اقتصاد توجه» (economy of attention) را از او گرفت. کتاب Bias of Communication (1951) را «سند بنیان‌گذاری» خود می‌دانست."],
            ["ای.آر. جی. ریچاردز (I.A. Richards)", "بنیان‌گذار «نقد نو». آموخت که زبان، ادراک را می‌سازد. ریشه‌ی مستقیم شعار «رسانه پیام است»."],
            ["اریک هاوِلوک (Eric Havelock)", "دانشمند ادبیات باستان و متخصص شفاهیّت. نشان داد که ذهنِ انسان پیش از کتابت، ساختاری کاملاً متفاوت داشت. مک‌لوهان این یافته را به بسط ادراک الکترونیکی تبدیل کرد."],
            ["والتِر اونگ (Walter Ong)", "حرفه‌مند «مطالعات شفاهی-نوشته». کتاب Orality and Literacy (1982) — که مک‌لوهان پیش از مرگش تأیید کرد — تکمیل‌کننده‌ی طرح او بود: از شفاهیّت تا نوشتار الکترونیکی."],
            ["نورتروپ فرای (Northrop Frye)", "همکار نزدیک در تورنتو. نقد ادبی و اسطوره‌شناسی. تأثیر عمیق در سبک ادبی و ارجاعات اساطیری مک‌لوهان."],
            ["جیمز جویس (James Joyce)", "Finnegans Wake منبع الهام مکرر. «زبان آوانگارد» و «بازی با کلمه» جویس، الگوی سبک مک‌لوهان شد."],
            ["توماس آکویناس و ارسطو", "فلسفه‌ی کلاسیک و کاتولیک. تأثیر عمیق در آثار دیرهنگام و دین‌محور (The New Millennium, 1994)."],
            ["ژاک الول (Jacques Ellul)", "نظریه‌پرداز فناوری و جامعه. تأثیر در نگاه انتقادی-هشداردهنده به «محیط فناوری»."],
        ],
        col_widths=[4.5, 11.5],
    )
    D.page_break()


def ch4(D):
    D.h1("زمینه‌ی فکری: سه ستون و یک روش", num="۴")

    D.h2("۴.۱. مرکز مطالعات رسانه‌ای: جایی که رشته زاده شد")
    D.para("در ۱۹۶۳، مک‌لوهان «مرکز مطالعات رسانه‌ای» (Centre for the Study of Communication) را در دانشگاه تورنتو بنیان نهاد — نهادی‌ای که بعدا‌ً به «مرکز فرهنگ و فناوری» (Centre for Culture and Technology) تبدیل شد. این مرکز، نقطه‌ی عطف نهادی‌ای بود: مطالعات رسانه، از یک «صندلیِ تدریس» به یک «حوزه‌ی مستقل پژوهش» ارتقا یافت. مرکز، محیطی‌ای بود که در آن شاگردان (از جمله دریک دو کرکووف، Derrick de Kerckhove) با روش «تحلیل الگو» آشنا شدند و اکولوژی رسانه را به‌شکل‌های مختلف بسط دادند.")

    D.h2("۴.۲. سه ستون فکری")
    D.para("فکر مک‌لوهان بر سه ستون استوار است که هرکدام از یک پیشرو گرفته شده و به سوی رسانه‌های الکترونیکی بسط یافته‌اند:")

    D.h3("ستون اول: هارولد اینیس و «سوگیری رسانه»")
    D.para("اینیس، اقتصاددان و تاریخ‌دان کانادایی، در کتاب‌های Empire and Communications (1950) و The Bias of Communication (1951) نشان داد که هر رسانه، بسته به ماهیتش، «سوگیری» (bias) دارد: یا در «زمان» (مانند سنگ و پوسته که بادوام‌اند اما سنگین) یا در «فضا» (مانند کاغذ و الکترونیک که سبک‌اند اما زودگذر). امپراتوری‌ها، وقتی تعادل میان این دو سوگیری را از دست می‌دهند، می‌افتند. مک‌لوهان این چارچوب را گرفت و آن را به «رسانه‌های الکترونیکی» بسط داد: تلگراف، تلویزیون و اینترنت، سوگیری‌های فضاییِ شدید (سرعت و هم‌زمانی) دارند و جهان را «فشرده» می‌کنند — و این فشرده‌سازی، همان «روستای جهانی» است.")

    D.h3("ستون دوم: هاوِلوک و «شفاهیّت»")
    D.para("اریک هاوِلوک، متخصص ادبیات باستان، در کتاب‌هایی مانند Preface to the Study of Homer (1963) نشان داد که فرهنگ‌های شفاهی، ادراکی‌ای «تجمعی و مشارکتی» دارند؛ در حالی‌که فرهنگ‌های نوشتاری، ادراک را «فردی و خطی» می‌سازند. مک‌لوهان این یافته را به عصر الکترونیکی گسترش داد: رسانه‌های الکترونیکی (تلویزیون، اینترنت) ما را به حالت «تبریزالیزه‌ی مجدد» (re-tribalization) برمی‌گردانند — نه به «قبایل» قیچی‌شده، بلکه به «مشارکت ادراکیِ تجمعی» در مقیاس جهانی.")

    D.h3("ستون سوم: اونگ و «محوطه‌ی الکترونیکی»")
    D.para("والتِر اونگ، در کتاب‌هایی مانند Orality and Literacy (1982) و The Futures of Writing (1977)، نشان داد که «نوشتار الکترونیکی» (electronic writing) مرحله‌ی تازه‌ای پس از خط و کتابت است. مک‌لوهان پیش از مرگش این کتاب را تأیید کرد؛ و در آن، طرح خود را تکمیل یافت: از شفاهیّت → کتابت → خط چاپ → الکترونیک. این «چارچوب تاریخی-رسانه‌ای»، ابزاری‌ای شد که مک‌لوهان برای تحلیل هر فناوری به کار می‌گرفت.")

    D.h2("۴.۳. روش‌شناسی: تحلیل الگو به‌جای تحلیل کمّی")
    D.para("روش مک‌لوهان، از نظر روش‌شناختی، «تحلیل الگو» (pattern analysis) بود، نه «آزمون فرضیه». او معتقد بود رسانه‌ها «به‌شکل الگو» عمل می‌کنند، نه به‌شکل متغیرهای کمّی قابل‌اندازه‌گیری. این روش، از «نقد نو» (ریشه‌ی کمبریج) و از «مباحثه‌ی کلاسیک» (dialectic) الهام گرفته بود. در فصل ۱۱ (نقد روش‌شناسی) می‌بینیم که همین انتخاب، بزرگ‌ترین نقطه‌ی ضعف او از نظر منتقدان بوده است.")

    D.h2("۴.۴. شبکه‌ی تأثیرات: چگونه مک‌لوهان شکل گرفت")
    D.para("این شبکه‌ی تأثیرات، نشان می‌دهد که مک‌لوهان «مجردِ یک رسانه‌شناس» نبود؛ او «انسانِ ادبیاتی» بود که «ادبیات، فلسفه، تاریخ، دین و فناوری» را در «موزائیکی» ادغام می‌کرد. این «تعامل‌گرایی» (interdisciplinarity)، «امضا» فکری اوست و دلیل «محبوبیت» و در عین حال «گم‌راه‌کنندگی» آثارش است.")

    D.h2("۴.۵. «بُعد کانادایی» فکری")
    D.para("یکی از «وجه‌های نادیده‌شده» فکر مک‌لوهان، «بُعد کانادایی» آن است. مک‌لوهان، «کانادا» را به‌عنوان «آزمایشگاه» ایده‌هایش می‌دانست: «کانادا، کشوری‌ای است که «فصل‌ها» آن (زمستان، تابستان) «بُعد زمانی» را تقویت می‌کنند و «گسترده‌بودن» آن «بُعد فضایی» را.» این «بُعد کانادایی»، «روستای جهانی» را از یک «مفهوم انتزاعی» به یک «تجربه‌ی جغرافیایی» تبدیل می‌کند: «کانادا، «روستای جهانی» را «به شکل طبیعی» تجربه می‌کند — چون «فاصله‌ها» آن، «هم‌زمانی» الکترونیکی را «تشدید» می‌کنند.")
    D.callout("تمرین ۴:", "یکی از سه ستون (اینیس/هاوِلوک/اونگ) را انتخاب کنید و توضیح دهید چگونه مک‌لوهان آن را به عصر الکترونیکی بسط داده است. سپس یک فناوری معاصر (مثلا‌ً هوش مصنوعی یا شبکه‌های اجتماعی) را در چارچوب همان ستون تحلیل کنید.")
    D.page_break()
